import re

def parse(lines):
    title = re.compile(r"^Version (\w+) section '([^']*)' contains (\d+) entr")
    addr = re.compile(r"^\s*Addr:\s*(\S+)\s+Offset:\s*(\S+)\s+Link:\s*(\d+)\s*\(([^)]*)\)")
    sym = re.compile(r"^\s*([0-9a-fA-F]+):\s+(\S.*)$")
    ent = re.compile(r"(\S+)\s+\(([^)]*)\)")
    need = re.compile(r"^\s*(\S+):\s+Version:\s*(\d+)\s+File:\s*(\S+)\s+Cnt:\s*(\d+)")
    aux = re.compile(r"^\s*(\S+):\s+Name:\s*(\S+)\s+Flags:\s*(.*?)\s+Version:\s*(\d+)")
    vdef = re.compile(r"^\s*(\S+):\s+Rev:\s*(\d+)\s+Flags:\s*(.*?)\s+Index:\s*(\d+)\s+Cnt:\s*(\d+)\s+Name:\s*(\S+)")
    par = re.compile(r"^\s*(\S+):\s+Parent\s+\d+:\s*(\S+)")
    secs = {"name": "sections", "kind": "table", "lines": [], "records": []}
    syms = {"name": "version_symbols", "kind": "table", "lines": [], "records": []}
    needs = {"name": "version_needs", "kind": "table", "lines": [], "records": []}
    defs = {"name": "version_definitions", "kind": "table", "lines": [], "records": []}
    kind = None
    cur = None
    curfile = None
    lastdef = None
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        m = title.match(l)
        if m:
            kind = m.group(1)
            cur = {"Section type": kind, "Section": m.group(2), "Entries": int(m.group(3)), "Addr": "", "Offset": "", "Link": "", "Link section": ""}
            secs["records"].append(cur)
            secs["lines"].append(i)
            continue
        m = addr.match(l)
        if m and cur is not None:
            cur["Addr"] = m.group(1)
            cur["Offset"] = m.group(2)
            cur["Link"] = m.group(3)
            cur["Link section"] = m.group(4)
            secs["lines"].append(i)
            continue
        if kind == "needs":
            m = need.match(l)
            if m:
                curfile = (m.group(3), m.group(2), m.group(4))
                needs["lines"].append(i)
                continue
            m = aux.match(l)
            if m:
                f = curfile or ("", "", "")
                needs["records"].append({"File": f[0], "File version": f[1], "Cnt": f[2], "Offset": m.group(1), "Name": m.group(2), "Flags": m.group(3), "Version": m.group(4)})
                needs["lines"].append(i)
                continue
        elif kind == "definition":
            m = vdef.match(l)
            if m:
                lastdef = {"Offset": m.group(1), "Rev": m.group(2), "Flags": m.group(3), "Index": m.group(4), "Cnt": m.group(5), "Name": m.group(6), "Parents": ""}
                defs["records"].append(lastdef)
                defs["lines"].append(i)
                continue
            m = par.match(l)
            if m and lastdef is not None:
                lastdef["Parents"] = (lastdef["Parents"] + " " + m.group(2)).strip()
                defs["lines"].append(i)
                continue
        elif kind == "symbols":
            m = sym.match(l)
            if m:
                es = ent.findall(m.group(2))
                if es:
                    base = int(m.group(1), 16)
                    for k, e in enumerate(es):
                        syms["records"].append({"Index": base + k, "Version": e[0], "Name": e[1]})
                    syms["lines"].append(i)
                    continue
    return {"blocks": [b for b in (secs, syms, needs, defs) if b["lines"]], "skip": []}
